with fields as (select jsonb_agg(jsonb_build_object('key',key,'sectionKey','urinary','label',label,'type','select','sequence',sequence,'required',false,'accessibilityLabel',label,'helpText','Legacy three-state Review of Systems value. Stored codes yes/no/na retain legacy YES/NO/N/A displays.','maxLength',null,'minimum',null,'maximum',null,'precision',null,'unit',null,'codeSystem',null,'options',jsonb_build_array(jsonb_build_object('code','yes','display','YES'),jsonb_build_object('code','no','display','NO'),jsonb_build_object('code','na','display','N/A')),'repeatMinimum',null,'repeatMaximum',null,'children','[]'::jsonb,'readOnly',false) order by sequence) value from (values ('polyuria','Polyuria',10),('polydypsia','Polydipsia',20),('dysuria','Dysuria',30),('hematuria','Hematuria',40),('frequency','Urinary frequency',50),('urgency','Urinary urgency',60),('incontinence','Incontinence',70),('renal_stones','Renal stones',80),('utis','Urinary tract infections',90),('hesitancy','Urinary hesitancy',100),('dribbling','Urinary dribbling',110),('stream','Weak urinary stream',120),('nocturia','Nocturia',130),('erections','Erections concerns',140),('ejaculations','Ejaculations concerns',150)) source(key,label,sequence)), schema as (select jsonb_build_object('stableKey','legacy.rosurinary','name','Review of Systems Urinary','purpose','Legacy Review of Systems urinary compatibility capture.','contextScope','encounter','owningService','clinical_operations','capability','encounters.auth_a','signaturePolicy','author-only','sections',jsonb_build_array(jsonb_build_object('key','urinary','title','Urinary','sequence',10,'description','Mapped from legacy form_ros urinary fields.')),'fields',value,'rules','[]'::jsonb) schema_json from fields)
update clinical_form_definitions set effective_revision=1,updated_at=now(),updated_by='legacy-adoption-seed' where stable_key='legacy.rosurinary' and effective_revision is null;
